const dictionaries = { ar: new Map(), en: new Map(), ru: new Map() };
for (const [arabic, english, russian] of entries) {
  dictionaries.en.set(arabic, english);
  dictionaries.ru.set(arabic, russian);
}

const dynamic = [
  [/^أهلًا\s+(.+)$/, (m, lang) => lang === "en" ? `Hello ${m[1]}` : `Здравствуйте, ${m[1]}`],
  [/^محجوز:\s*(.+)$/, (m, lang) => lang === "en" ? `Held: ${m[1]}` : `Резерв: ${m[1]}`],
  [/^تفاصيل\s+(.+)$/, (m, lang) => lang === "en" ? `Details: ${m[1]}` : `Детали: ${m[1]}`],
  [/^طلب\s+#(.+)$/, (m, lang) => lang === "en" ? `Request #${m[1]}` : `Запрос №${m[1]}`],
  [/^(\d+)\s+طلب$/, (m, lang) => lang === "en" ? `${m[1]} requests` : `${m[1]} запр.`],
  [/^(\d+)\s+فرصة متاحة$/, (m, lang) => lang === "en" ? `${m[1]} opportunities available` : `${m[1]} доступных возможн.`],
  [/^آخر فحص:\s*(.+)$/, (m, lang) => lang === "en" ? `Last checked: ${m[1]}` : `Последняя проверка: ${m[1]}`],
  [/^انتهاء مهلة الاعتراض:\s*(.+)$/, (m, lang) => lang === "en" ? `Dispute window ends: ${m[1]}` : `Период спора заканчивается: ${m[1]}`],
  [/^مدفوعة حتى\s+(.+)$/, (m, lang) => lang === "en" ? `Paid until ${m[1]}` : `Оплачено до ${m[1]}`],
  [/^تحديث\s+(.+)$/, (m, lang) => lang === "en" ? `Update ${m[1]}` : `Обновление ${m[1]}`],
  [/^تاريخ التسجيل\s+(.+)$/, (m, lang) => lang === "en" ? `Registered ${m[1]}` : `Регистрация: ${m[1]}`],
  [/^سبب النزاع:\s*(.+)$/, (m, lang) => lang === "en" ? `Dispute reason: ${m[1]}` : `Причина спора: ${m[1]}`],
  [/^متابعة التطبيق لمدة\s+(.+)$/, (m, lang) => lang === "en" ? `App support for ${m[1]}` : `Сопровождение приложения: ${m[1]}`],
  [/^عمولة النشر:\s*(.+)$/, (m, lang) => lang === "en" ? `Publishing commission: ${m[1]}` : `Комиссия публикации: ${m[1]}`],
  [/^الحد الأدنى\s+(.+)$/, (m, lang) => lang === "en" ? `Minimum ${m[1]}` : `Минимум ${m[1]}`],
  [/^رصيدك المتاح\s+(.+)$/, (m, lang) => lang === "en" ? `Available balance ${m[1]}` : `Доступный баланс ${m[1]}`],
  [/^حصتك\s+(.+?)(?:\.\s*|$)/, (m, lang) => lang === "en" ? `Your share ${m[1]}.` : `Ваша доля ${m[1]}.`],
  [/^كمية العملة التي أرسلت فعليًا\s*\((.+)\)$/, (m, lang) => lang === "en" ? `Actual crypto amount sent (${m[1]})` : `Фактически отправленная криптовалюта (${m[1]})`],
];

function normalize(value) {
  return String(value).replace(/\s+/g, " ").trim();
}

export function getLanguage() {
  if (typeof window === "undefined") return "ar";
  const stored = window.localStorage.getItem(STORAGE_KEY);
  return languageByCode[stored] ? stored : "ar";
}

function preserveWhitespace(original, translated) {
  const leading = original.match(/^\s*/)?.[0] || "";
  const trailing = original.match(/\s*$/)?.[0] || "";
  return `${leading}${translated}${trailing}`;
}

export function translateValue(value, language = getLanguage()) {
  if (language === "ar" || value == null) return value;
  const source = normalize(value);
  if (!source) return value;
  const exact = dictionaries[language].get(source);
  if (exact) return preserveWhitespace(value, exact);
  for (const [pattern, replacement] of dynamic) {
    const match = source.match(pattern);
    if (match) return preserveWhitespace(value, replacement(match, language));
  }
  return value;
}

const originals = new WeakMap();

function isIgnored(node) {
  return node?.nodeType === Node.ELEMENT_NODE && node.closest("[data-i18n-ignore]");
}

export function translateDocument(root = document, language = getLanguage()) {
  if (!root) return;
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
  const textNodes = [];
  let node;
  while ((node = walker.nextNode())) {
    if (!node.parentElement || isIgnored(node.parentElement)) continue;
    textNodes.push(node);
  }
  for (const textNode of textNodes) {
    if (!originals.has(textNode)) originals.set(textNode, textNode.nodeValue);
    const source = originals.get(textNode);
    const translated = language === "ar" ? source : translateValue(source, language);
    if (textNode.nodeValue !== translated) textNode.nodeValue = translated;
  }
  const elements = root.querySelectorAll?.("[aria-label], [placeholder], [title], [alt]") || [];
  for (const element of elements) {
    if (element.closest("[data-i18n-ignore]")) continue;
    let attrs = originals.get(element);
    if (!attrs) {
      attrs = {};
      for (const name of ["aria-label", "placeholder", "title", "alt"]) {
        if (element.hasAttribute(name)) attrs[name] = element.getAttribute(name);
      }
      originals.set(element, attrs);
    }
    for (const [name, source] of Object.entries(attrs)) {
      const translated = language === "ar" ? source : translateValue(source, language);
      if (element.getAttribute(name) !== translated) element.setAttribute(name, translated);
    }
  }
}

export function applyLanguage(language) {
  const selected = languageByCode[language] ? language : "ar";
  const option = languageByCode[selected];
  if (typeof document !== "undefined") {
    document.documentElement.lang = selected === "en" ? "en" : selected === "ru" ? "ru" : "ar";
    document.documentElement.dir = option.dir;
    document.body?.setAttribute("dir", option.dir);
    document.body?.setAttribute("data-language", selected);
    translateDocument(document, selected);
  }
  return selected;
}

export function setLanguage(language) {
  const selected = languageByCode[language] ? language : "ar";
  if (typeof window !== "undefined") window.localStorage.setItem(STORAGE_KEY, selected);
  applyLanguage(selected);
  if (typeof window !== "undefined") window.dispatchEvent(new CustomEvent("dorucenie-language", { detail: selected }));
  return selected;
}

export function useLanguage() {
  const [language, setCurrent] = useState(getLanguage);
  useEffect(() => {
    const handler = (event) => setCurrent(event.detail || getLanguage());
    window.addEventListener("dorucenie-language", handler);
    return () => window.removeEventListener("dorucenie-language", handler);
  }, []);
  return [language, setLanguage];
}

export function LanguageSwitcher({ compact = false }) {
  const [language, changeLanguage] = useLanguage();
  return createElement(
    "label",
    { className: `language-switcher${compact ? " compact" : ""}`, "data-i18n-ignore": "true" },
    createElement("span", { className: "sr-only" }, "Language"),
    createElement(
      "select",
      { "aria-label": "Language", value: language, onChange: (event) => changeLanguage(event.target.value) },
      LANGUAGE_OPTIONS.map((option) => createElement("option", { key: option.code, value: option.code }, `${option.short} · ${option.label}`)),
    ),
  );
}

export function currentLanguageMeta(language = getLanguage()) {
  return languageByCode[language] || languageByCode.ar;
}
